// CMS Filters
document.addEventListener("DOMContentLoaded", () => {
  const filterEls = document.querySelectorAll("[data-filter]");
  const storyEls = document.querySelectorAll("[data-cats-source]");
  const modeEls = document.querySelectorAll("[data-filter-mode]");

  if (!filterEls.length || !storyEls.length) return;

  const normalize = (s) =>
    (s || "")
      .toString()
      .toLowerCase()
      .trim()
      .replace(/&/g, "en")
      .replace(/[^\w\s-]/g, "")
      .replace(/\s+/g, "-");

  const parseCats = (raw) =>
    (raw || "")
      .split(/,|•|\n|\r|\t/gi)
      .map(normalize)
      .filter(Boolean);

  const storyData = Array.from(storyEls).map((storyEl) => {
    const catsTextEl = storyEl.querySelector(".cats-text");
    const raw = catsTextEl ? catsTextEl.textContent : "";
    return { storyEl, cats: parseCats(raw) };
  });

  let selected = new Set();
  let mode = "or";

  const setActiveUI = () => {
    filterEls.forEach((el) => {
      const val = normalize(el.getAttribute("data-filter"));
      const isAlles = val === "alles";
      const isActive = isAlles ? selected.size === 0 : selected.has(val);
      el.classList.toggle("is-active", isActive);
    });

    modeEls.forEach((el) => {
      const m = normalize(el.getAttribute("data-filter-mode"));
      el.classList.toggle("is-active", m === mode);
    });
  };

  const matches = (cats) => {
    if (selected.size === 0) return true;
    const sel = Array.from(selected);
    if (mode === "and") return sel.every((s) => cats.includes(s));
    return sel.some((s) => cats.includes(s));
  };

  const updateUrl = () => {
    const params = new URLSearchParams(window.location.search);
    const filters = Array.from(selected).join(",");

    if (filters) {
      params.set("filter", filters);
    } else {
      params.delete("filter");
    }

    if (mode === "and") {
      params.set("mode", "and");
    } else {
      params.delete("mode");
    }

    const query = params.toString();
    const newUrl = query
      ? `${window.location.pathname}?${query}`
      : window.location.pathname;

    history.replaceState(null, "", newUrl);
  };

  const render = () => {
    storyData.forEach(({ storyEl, cats }) => {
      storyEl.style.display = matches(cats) ? "" : "none";
    });
    setActiveUI();
    updateUrl();
  };

  const toggleFilter = (value) => {
    const v = normalize(value);

    if (v === "alles") {
      selected.clear();
      render();
      return;
    }

    if (selected.has(v)) {
      selected.delete(v);
    } else {
      selected.add(v);
    }

    render();
  };

  const params = new URLSearchParams(window.location.search);
  const filterParam = params.get("filter");
  const modeParam = normalize(params.get("mode"));

  if (filterParam) {
    filterParam
      .split(",")
      .map(normalize)
      .filter(Boolean)
      .forEach((v) => selected.add(v));
  }

  if (modeParam === "and" || modeParam === "or") {
    mode = modeParam;
  }

  filterEls.forEach((el) => {
    el.addEventListener("click", (e) => {
      e.preventDefault();
      toggleFilter(el.getAttribute("data-filter"));
    });
  });

  modeEls.forEach((el) => {
    el.addEventListener("click", (e) => {
      e.preventDefault();
      const m = normalize(el.getAttribute("data-filter-mode"));
      if (m === "and" || m === "or") {
        mode = m;
        render();
      }
    });
  });

  render();
});

// Mega Menu
document.addEventListener("DOMContentLoaded", () => {
  const mobileBreakpoint = 991;

  const navbar = document.querySelector(".navbar");
  const megaMenu = document.querySelector(".mega_menu_wrapper");
  const overlay = document.querySelector(".page_overlay");
  const triggers = Array.from(document.querySelectorAll("[data_menu_trigger]"));
  const panels = Array.from(document.querySelectorAll("[data_menu_panel]"));

  if (!navbar || !megaMenu || !triggers.length || !panels.length || typeof gsap === "undefined") return;

  let activeKey = null;
  let isOpen = false;
  let closeTimer = null;
  let currentPanel = null;
  let mobileAnimating = false;

  function isMobile() {
    return window.innerWidth <= mobileBreakpoint;
  }

  function getPanel(key) {
    return document.querySelector(`[data_menu_panel="${key}"]`);
  }

  function setActiveTrigger(key) {
    triggers.forEach((trigger) => {
      trigger.classList.toggle("is_active", trigger.getAttribute("data_menu_trigger") === key);
    });
  }

  function getPanelHeight(panel) {
    const prev = panel.style.display;
    panel.style.display = "flex";
    const height = panel.offsetHeight;
    panel.style.display = prev;
    return height;
  }

  function openDesktopMenu(key) {
    const nextPanel = getPanel(key);
    if (!nextPanel) return;

    clearTimeout(closeTimer);
    setActiveTrigger(key);

    if (!isOpen) {
      activeKey = key;
      currentPanel = nextPanel;
      isOpen = true;

      gsap.set(nextPanel, { display: "flex" });

      const targetHeight = getPanelHeight(nextPanel);

      const tl = gsap.timeline();

      if (overlay) {
        tl.to(overlay, {
          autoAlpha: 1,
          duration: 0.2,
          onStart: () => overlay.style.pointerEvents = "auto"
        }, 0);
      }

      tl.to(megaMenu, {
        height: targetHeight,
        duration: 0.45,
        ease: "power3.out"
      }, 0);

      tl.fromTo(nextPanel,
        { autoAlpha: 0, y: 16 },
        { autoAlpha: 1, y: 0, duration: 0.35 },
        0.08
      );

      return;
    }

    if (activeKey === key) return;

    switchDesktopPanel(key);
  }

  function switchDesktopPanel(key) {
    const nextPanel = getPanel(key);
    if (!nextPanel || nextPanel === currentPanel) return;

    const oldPanel = currentPanel;
    activeKey = key;
    currentPanel = nextPanel;
    setActiveTrigger(key);

    gsap.set(nextPanel, { display: "flex", autoAlpha: 0, y: 16 });

    const targetHeight = getPanelHeight(nextPanel);

    const tl = gsap.timeline();

    tl.to(oldPanel, { autoAlpha: 0, y: -8, duration: 0.18 }, 0);

    tl.to(megaMenu, {
      height: targetHeight,
      duration: 0.35,
      ease: "power3.out"
    }, 0);

    tl.add(() => gsap.set(oldPanel, { display: "none" }));

    tl.to(nextPanel, {
      autoAlpha: 1,
      y: 0,
      duration: 0.28
    }, 0.08);
  }

  function closeDesktopMenu() {
    clearTimeout(closeTimer);
    if (!isOpen) return;

    isOpen = false;
    activeKey = null;
    setActiveTrigger(null);

    const tl = gsap.timeline({
      onComplete: () => {
        panels.forEach(p => gsap.set(p, { display: "none", autoAlpha: 0 }));
        if (overlay) overlay.style.pointerEvents = "none";
        currentPanel = null;
      }
    });

    if (currentPanel) {
      tl.to(currentPanel, { autoAlpha: 0, y: 10, duration: 0.2 }, 0);
    }

    tl.to(megaMenu, {
      height: 0,
      duration: 0.35,
      ease: "power3.inOut"
    }, 0.05);

    if (overlay) {
      tl.to(overlay, { autoAlpha: 0, duration: 0.2 }, 0);
    }
  }

  function scheduleClose() {
    clearTimeout(closeTimer);
    closeTimer = setTimeout(closeDesktopMenu, 120);
  }

 function openMobilePanel(key) {
  const panel = getPanel(key);
  if (!panel || mobileAnimating) return;

  const oldPanel = currentPanel;
  const isSame = oldPanel === panel;

  mobileAnimating = true;

  const tl = gsap.timeline({
    onComplete: () => {
      mobileAnimating = false;
    }
  });

  if (oldPanel) {
    tl.to(oldPanel, {
      height: 0,
      duration: 0.2,
      ease: "power2.inOut",
      onStart: () => {
        oldPanel.style.overflow = "hidden";
      },
      onComplete: () => {
        oldPanel.style.display = "none";
      }
    }, 0);
  }

  if (isSame) {
    currentPanel = null;
    activeKey = null;
    setActiveTrigger(null);
    return;
  }

  panel.style.display = "flex";
  panel.style.overflow = "hidden";

  const height = panel.scrollHeight;

  tl.fromTo(
    panel,
    { height: 0 },
    {
      height: height,
      duration: 0.28,
      ease: "power2.out",
      onComplete: () => {
        panel.style.height = "auto";
      }
    },
    oldPanel ? 0.05 : 0
  );

  currentPanel = panel;
  activeKey = key;
  setActiveTrigger(key);
}

function closeMobilePanel() {
  if (!currentPanel || mobileAnimating) return;

  const panelToClose = currentPanel;
  mobileAnimating = true;

  gsap.to(panelToClose, {
    height: 0,
    duration: 0.2,
    ease: "power2.inOut",
    onStart: () => {
      panelToClose.style.overflow = "hidden";
    },
    onComplete: () => {
      panelToClose.style.display = "none";
      currentPanel = null;
      activeKey = null;
      setActiveTrigger(null);
      mobileAnimating = false;
    }
  });
}

  triggers.forEach(trigger => {
    const key = trigger.getAttribute("data_menu_trigger");

    trigger.addEventListener("mouseenter", () => {
      if (isMobile()) return;
      openDesktopMenu(key);
    });

    trigger.addEventListener("focus", () => {
      if (isMobile()) return;
      openDesktopMenu(key);
    });

    trigger.addEventListener("click", (e) => {
      if (!isMobile()) return;

      e.preventDefault();
      e.stopPropagation();

      openMobilePanel(key);
    });
  });

  navbar.addEventListener("mouseleave", () => {
    if (isMobile()) return;
    scheduleClose();
  });

  navbar.addEventListener("mouseenter", () => {
    if (isMobile()) return;
    clearTimeout(closeTimer);
  });

  if (overlay) {
    overlay.addEventListener("click", () => {
      if (!isMobile()) closeDesktopMenu();
    });
  }

  document.addEventListener("click", (e) => {
    if (!isMobile()) return;
    if (!navbar.contains(e.target)) closeMobilePanel();
  });

  document.addEventListener("keydown", (e) => {
    if (e.key === "Escape") {
      isMobile() ? closeMobilePanel() : closeDesktopMenu();
    }
  });

});


//GSAP Heading animations
gsap.registerPlugin(SplitText, ScrollTrigger);

const splitConfig = {
  lines: { duration: 0.8, stagger: 0.08 },
  words: { duration: 0.6, stagger: 0.06 },
  chars: { duration: 0.4, stagger: 0.01 }
}

function initMaskTextScrollReveal() {
  document.querySelectorAll('[data-split="heading"]').forEach(heading => {
    const type = heading.dataset.splitReveal || 'lines'
    const typesToSplit =
      type === 'lines' ? ['lines'] :
      type === 'words' ? ['lines','words'] :
      ['lines','words','chars']
    

    SplitText.create(heading, {
      type: typesToSplit.join(', '), 
      mask: 'lines', 
      autoSplit: true,
      linesClass: 'line',
      wordsClass: 'word',
      charsClass: 'letter',
      onSplit: function(instance) {
        const targets = instance[type] 
        const config = splitConfig[type] 
        
        return gsap.from(targets, {
          yPercent: 110,
          duration: config.duration,
          stagger: config.stagger,
          ease: 'expo.out',
          scrollTrigger: {
            trigger: heading,
            start: 'clamp(top 80%)',
            once: true
          }
        });
      }
    })
  })

}

document.addEventListener("DOMContentLoaded", () => {
  initMaskTextScrollReveal()
});

//Agenda filters
document.addEventListener("DOMContentLoaded", () => {
  const filters = document.querySelectorAll('input[type="checkbox"][data-filter-group][data-filter-value]');
  const items = document.querySelectorAll(".card_item");
  const noResults = document.querySelector(".no_results");

  if (!filters.length || !items.length) return;

  function getActive(group) {
    return [...document.querySelectorAll(`input[type="checkbox"][data-filter-group="${group}"]:checked`)]
      .map((el) => (el.getAttribute("data-filter-value") || "").toLowerCase().trim())
      .filter(Boolean);
  }

  function matches(itemValues, activeValues) {
    if (!activeValues.length) return true;
    return activeValues.some((v) => itemValues.includes(v));
  }

  function getTimeTags(dateString) {
    if (!dateString) return [];

    const eventDate = new Date(dateString);
    if (isNaN(eventDate)) return [];

    const now = new Date();
    const startOfToday = new Date(now.getFullYear(), now.getMonth(), now.getDate());
    const startOfEventDay = new Date(eventDate.getFullYear(), eventDate.getMonth(), eventDate.getDate());

    const day = startOfToday.getDay();
    const mondayOffset = day === 0 ? -6 : 1 - day;

    const startOfWeek = new Date(startOfToday);
    startOfWeek.setDate(startOfToday.getDate() + mondayOffset);

    const endOfWeek = new Date(startOfWeek);
    endOfWeek.setDate(startOfWeek.getDate() + 7);

    const startOfMonth = new Date(startOfToday.getFullYear(), startOfToday.getMonth(), 1);
    const endOfMonth = new Date(startOfToday.getFullYear(), startOfToday.getMonth() + 1, 1);

    const tags = [];

    if (startOfEventDay >= startOfWeek && startOfEventDay < endOfWeek) tags.push("week");
    if (startOfEventDay >= startOfMonth && startOfEventDay < endOfMonth) tags.push("month");
    if (startOfEventDay >= endOfMonth) tags.push("future");

    return tags;
  }

  function getSeasonTag(dateString) {
    if (!dateString) return [];

    const eventDate = new Date(dateString);
    if (isNaN(eventDate)) return [];

    const month = eventDate.getMonth() + 1;

    if (month === 12 || month === 1 || month === 2) return ["winter"];
    if (month >= 3 && month <= 5) return ["lente"];
    if (month >= 6 && month <= 8) return ["zomer"];
    return ["herfst"];
  }

  function hideItem(item) {
    item.style.opacity = "0";
    clearTimeout(item._hideTimer);
    item._hideTimer = setTimeout(() => {
      item.style.display = "none";
    }, 200);
  }

  function showItem(item) {
    clearTimeout(item._hideTimer);
    if (item.style.display === "none") {
      item.style.display = "";
      requestAnimationFrame(() => {
        item.style.opacity = "1";
      });
    } else {
      item.style.opacity = "1";
    }
  }

  function updateNoResults() {
    if (!noResults) return;
    const visible = [...items].some((item) => item.style.display !== "none");
    noResults.style.display = visible ? "none" : "block";
  }

  function updateFilters() {
    const activeTime = getActive("time");
    const activeSeason = getActive("season");

    items.forEach((item) => {
      const eventDate = item.getAttribute("data-event-date");
      const itemTime = getTimeTags(eventDate);
      const itemSeason = getSeasonTag(eventDate);

      const show = matches(itemTime, activeTime) && matches(itemSeason, activeSeason);

      if (show) {
        showItem(item);
      } else {
        hideItem(item);
      }
    });

    updateNoResults();
  }

  items.forEach((item) => {
    item.style.transition = "opacity 0.2s ease";
  });

  if (noResults) {
    noResults.style.display = "none";
  }

  filters.forEach((filter) => {
    filter.addEventListener("change", updateFilters);
  });

  updateFilters();
});

//Tabbar dropdown
document.addEventListener("DOMContentLoaded", function () {
  const mobileBreakpoint = 991;
  const wrappers = document.querySelectorAll(".tabbar_wrapper");

  wrappers.forEach((wrapper) => {
    const activeItem = wrapper.querySelector(".tab_item.is--active");
    const allItems = Array.from(wrapper.querySelectorAll(".tab_item"));
    const arrow = activeItem?.querySelector(".tabbar_dropdown");
    const otherItems = allItems.filter(item => !item.classList.contains("is--active"));

    if (!activeItem || otherItems.length === 0) return;

    let isOpen = false;
    let isAnimating = false;

    function setDesktopState() {
      allItems.forEach(item => {
        item.style.display = "";
        item.style.opacity = "";
        item.style.transform = "";
      });

      if (arrow) {
        gsap.set(arrow, { clearProps: "transform" });
      }
    }

    function setMobileClosedState() {
      activeItem.style.display = "flex";

      otherItems.forEach(item => {
        gsap.set(item, {
          display: "none",
          opacity: 0,
          y: -6
        });
      });

      if (arrow) {
        gsap.set(arrow, { rotate: 0 });
      }
    }

    function openMenu() {
      if (isAnimating) return;
      isAnimating = true;
      isOpen = true;

      gsap.set(otherItems, { display: "flex" });

      const tl = gsap.timeline({
        defaults: { ease: "power2.out" },
        onComplete: () => {
          isAnimating = false;
        }
      });

      if (arrow) {
        tl.to(arrow, { rotate: 180, duration: 0.22 }, 0);
      }

      tl.fromTo(
        otherItems,
        { opacity: 0, y: -6 },
        { opacity: 1, y: 0, duration: 0.22, stagger: 0.04 },
        0
      );
    }

    function closeMenu() {
      if (isAnimating) return;
      isAnimating = true;
      isOpen = false;

      const tl = gsap.timeline({
        defaults: { ease: "power2.inOut" },
        onComplete: () => {
          gsap.set(otherItems, { display: "none" });
          isAnimating = false;
        }
      });

      if (arrow) {
        tl.to(arrow, { rotate: 0, duration: 0.2 }, 0);
      }

      tl.to(
        otherItems,
        {
          opacity: 0,
          y: -6,
          duration: 0.16,
          stagger: 0.03
        },
        0
      );
    }

    function handleResize() {
      const isMobile = window.innerWidth <= mobileBreakpoint;

      if (!isMobile) {
        isOpen = false;
        isAnimating = false;
        setDesktopState();
      } else {
        if (isOpen) {
          activeItem.style.display = "flex";
          gsap.set(otherItems, {
            display: "flex",
            opacity: 1,
            y: 0
          });
          if (arrow) gsap.set(arrow, { rotate: 180 });
        } else {
          setMobileClosedState();
        }
      }
    }

    activeItem.style.cursor = "pointer";

    activeItem.addEventListener("click", function (e) {
      if (window.innerWidth > mobileBreakpoint) return;
      e.preventDefault();
      e.stopPropagation();

      if (isAnimating) return;

      if (isOpen) {
        closeMenu();
      } else {
        openMenu();
      }
    });

    document.addEventListener("click", function (e) {
      if (window.innerWidth > mobileBreakpoint) return;
      if (!wrapper.contains(e.target) && isOpen && !isAnimating) {
        closeMenu();
      }
    });

    window.addEventListener("resize", handleResize);

    handleResize();
  });
});

//Projecten filters
document.addEventListener("DOMContentLoaded", () => {
  const filters = document.querySelectorAll('input[type="checkbox"][data-filter-group][data-filter-value]');
  const items = document.querySelectorAll(".project_card");
  const noResults = document.querySelector(".no_results");

  if (!filters.length || !items.length) return;

  const normalize = (s) =>
    (s || "")
      .toString()
      .toLowerCase()
      .trim()
      .replace(/\s+/g, " ");

  const parseValues = (raw) =>
    (raw || "")
      .split(/,|•|\n|\r|\t/gi)
      .map(normalize)
      .filter(Boolean);

  function getActive(group) {
    return [...document.querySelectorAll(`input[type="checkbox"][data-filter-group="${group}"]:checked`)]
      .map((el) => normalize(el.getAttribute("data-filter-value")))
      .filter(Boolean);
  }

  function matches(itemValues, activeValues) {
    if (!activeValues.length) return true;
    return activeValues.some((v) => itemValues.includes(v));
  }

  const projectData = Array.from(items).map((item) => {
    const themes = parseValues(item.getAttribute("data-project-themes"));
    const status = parseValues(item.getAttribute("data-project-status"));
    const period = parseValues(item.getAttribute("data-project-period"));

    return {
      item,
      themes,
      status,
      period
    };
  });

  function hideItem(item) {
    item.style.opacity = "0";
    clearTimeout(item._hideTimer);
    item._hideTimer = setTimeout(() => {
      item.style.display = "none";
    }, 200);
  }

  function showItem(item) {
    clearTimeout(item._hideTimer);
    if (item.style.display === "none") {
      item.style.display = "";
      requestAnimationFrame(() => {
        item.style.opacity = "1";
      });
    } else {
      item.style.opacity = "1";
    }
  }

  function updateNoResults() {
    if (!noResults) return;
    const visible = [...items].some((item) => item.style.display !== "none");
    noResults.style.display = visible ? "none" : "block";
  }

  function updateFilters() {
    const activeThemes = getActive("themes");
    const activeStatus = getActive("status");
    const activePeriod = getActive("period");

    projectData.forEach(({ item, themes, status, period }) => {
      const show =
        matches(themes, activeThemes) &&
        matches(status, activeStatus) &&
        matches(period, activePeriod);

      if (show) {
        showItem(item);
      } else {
        hideItem(item);
      }
    });

    updateNoResults();
  }

  items.forEach((item) => {
    item.style.transition = "opacity 0.2s ease";
  });

  if (noResults) {
    noResults.style.display = "none";
  }

  filters.forEach((filter) => {
    filter.addEventListener("change", updateFilters);
  });

  updateFilters();
});

// Search
document.addEventListener("DOMContentLoaded", () => {
  const triggers = document.querySelectorAll(".search_icon");
  const modal = document.querySelector(".search_modal");

  if (!triggers.length || !modal || typeof gsap === "undefined") return;

  let isOpen = false;
  let isAnimating = false;

  gsap.set(modal, {
    display: "none",
    opacity: 0,
    y: -8
  });

  function openModal() {
    if (isOpen || isAnimating) return;
    isAnimating = true;
    isOpen = true;

    gsap.set(modal, { display: "flex" });

    gsap.to(modal, {
      opacity: 1,
      y: 0,
      duration: 0.22,
      ease: "power2.out",
      onComplete: () => {
        isAnimating = false;
        const input = modal.querySelector("input, .w-input");
        if (input) input.focus();
      }
    });
  }

  function closeModal() {
    if (!isOpen || isAnimating) return;
    isAnimating = true;
    isOpen = false;

    gsap.to(modal, {
      opacity: 0,
      y: -8,
      duration: 0.18,
      ease: "power2.in",
      onComplete: () => {
        gsap.set(modal, { display: "none" });
        isAnimating = false;
      }
    });
  }

  triggers.forEach((trigger) => {
    trigger.addEventListener("click", (e) => {
      e.preventDefault();
      e.stopPropagation();
      isOpen ? closeModal() : openModal();
    });
  });
  
  const closeTriggers = document.querySelectorAll(".close_search_icon");

closeTriggers.forEach((btn) => {
  btn.addEventListener("click", (e) => {
    e.preventDefault();
    e.stopPropagation();
    closeModal();
  });
});

  modal.addEventListener("click", (e) => {
    if (e.target === modal) {
      closeModal();
    }
  });

  document.addEventListener("keydown", (e) => {
    if (e.key === "Escape") {
      closeModal();
    }
  });

  document.addEventListener("click", (e) => {
    const clickedTrigger = e.target.closest(".search_icon");
    const clickedInsideModal = e.target.closest(".search_modal");

    if (!clickedTrigger && !clickedInsideModal && isOpen) {
      closeModal();
    }
  });
});

// SplitText animation
gsap.registerPlugin(ScrollTrigger, SplitText)
  
function initHighlightText(){

  let splitHeadingTargets = document.querySelectorAll("[data-highlight-text]")
  splitHeadingTargets.forEach((heading) => {
    
    const scrollStart = heading.getAttribute("data-highlight-scroll-start") || "top 90%"
    const scrollEnd = heading.getAttribute("data-highlight-scroll-end") || "center 40%"
    const fadedValue = heading.getAttribute("data-highlight-fade") || 0.2 // Opacity of letter
    const staggerValue =  heading.getAttribute("data-highlight-stagger") || 0.1 // Smoother reveal
    
    new SplitText(heading, {
      type: "words, chars",
      autoSplit: true,
      onSplit(self) {
        let ctx = gsap.context(() => {
          let tl = gsap.timeline({
            scrollTrigger: {
              scrub: true,
              trigger: heading, 
              start: scrollStart,
              end: scrollEnd,
            }
          })
          tl.from(self.chars,{
            autoAlpha: fadedValue,
            stagger: staggerValue,
            ease: "linear"
          })
        });
        return ctx; // return our animations so GSAP can clean them up when onSplit fires
      }
    });    
  });
}

// Initialize Highlight Text on Scroll
document.addEventListener("DOMContentLoaded", () =>{
  initHighlightText();
});
